/// Looks up a named entity by its exact (case-sensitive) name without
/// the `&` and `;`. Returns the code points, or null when the name is
/// not a valid HTML5 entity name.
pub fn lookup(name: []const u8) ?[2]u21 {
    var lo: usize = 0;
    var hi: usize = entities.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const cmp = std.mem.order(u8, entities[mid].name, name);
        switch (cmp) {
            .lt => lo = mid + 1,
            .gt => hi = mid,
            .eq => return .{ entities[mid].a, entities[mid].b },
        }
    }
    return null;
}

test "entities: corpus names resolve and unknown names do not" {
    try std.testing.expect(lookup("amp") != null);
    try std.testing.expect(lookup("copy") != null);
    try std.testing.expect(lookup("ouml") != null);
    try std.testing.expect(lookup("AElig") != null);
    try std.testing.expect(lookup("Dcaron") != null);
    try std.testing.expect(lookup("frac34") != null);
    try std.testing.expect(lookup("HilbertSpace") != null);
    try std.testing.expect(lookup("DifferentialD") != null);
    try std.testing.expect(lookup("ClockwiseContourIntegral") != null);
    try std.testing.expect(lookup("ngE") != null);
    try std.testing.expect(lookup("nbsp") != null);
    try std.testing.expect(lookup("quot") != null);
    try std.testing.expect(lookup("gt") != null);
    try std.testing.expect(lookup("lt") != null);
    try std.testing.expect(lookup("auml") != null);
    try std.testing.expect(lookup("MadeUpEntity") == null);
    try std.testing.expect(lookup("ThisIsNotDefined") == null);
    try std.testing.expectEqual(@as(?[2]u21, .{ 0x26, 0 }), lookup("amp"));
    try std.testing.expectEqual(@as(?[2]u21, .{ 0x2267, 0x338 }), lookup("ngE"));
}

/// The decoded form of an entity or numeric character reference: its UTF-8
/// bytes and the index just past the terminating `;` in the source.
pub const Decoded = struct {
    bytes: [8]u8,
    len: u8,
    next: usize,
};

/// Decodes the entity or numeric character reference whose `&` is at
/// `src[amp]`, mirroring the reference implementation's §2.5 rules: named
/// references must be a valid HTML5 entity name followed by `;`; decimal
/// references take 1-7 digits, hexadecimal 1-6; code point 0, surrogates,
/// and values at or above U+110000 become U+FFFD. Returns null when no
/// reference starts at `amp` (the `&` is literal text).
pub fn decodeAt(src: []const u8, amp: usize) ?Decoded {
    if (amp + 2 > src.len or src[amp] != '&') return null;
    if (src[amp + 1] == '#') return decodeNumeric(src, amp);
    return decodeNamed(src, amp);
}

fn decodeNumeric(src: []const u8, amp: usize) ?Decoded {
    var i = amp + 2;
    var base: u32 = 10;
    var max_digits: usize = 7;
    if (i < src.len and (src[i] == 'x' or src[i] == 'X')) {
        i += 1;
        base = 16;
        max_digits = 6;
    }
    const digit_start = i;
    var cp: u32 = 0;
    while (i < src.len) : (i += 1) {
        const c = src[i];
        const d: u32 = switch (c) {
            '0'...'9' => c - '0',
            'a'...'f' => if (base == 16) c - 'a' + 10 else break,
            'A'...'F' => if (base == 16) c - 'A' + 10 else break,
            else => break,
        };
        cp = @min(cp * base + d, 0x110000);
    }
    const num_digits = i - digit_start;
    if (num_digits == 0 or num_digits > max_digits or i >= src.len or src[i] != ';') return null;
    if (cp == 0 or (cp >= 0xD800 and cp <= 0xDFFF) or cp >= 0x110000) cp = 0xFFFD;
    var out: [8]u8 = undefined;
    const len = encodeUtf8(@intCast(cp), &out);
    return .{ .bytes = out, .len = len, .next = i + 1 };
}

fn decodeNamed(src: []const u8, amp: usize) ?Decoded {
    var i = amp + 1;
    while (i < src.len and src[i] != ';' and src[i] != ' ') : (i += 1) {}
    if (i >= src.len or src[i] != ';') return null;
    const cps = lookup(src[amp + 1 .. i]) orelse return null;
    var out: [8]u8 = undefined;
    var len: u8 = encodeUtf8(cps[0], &out);
    if (cps[1] != 0) len += encodeUtf8(cps[1], out[len..]);
    return .{ .bytes = out, .len = len, .next = i + 1 };
}

/// UTF-8 encodes `cp` into `out` (at most 4 bytes) and returns its length.
fn encodeUtf8(cp: u21, out: []u8) u8 {
    if (cp < 0x80) {
        out[0] = @intCast(cp);
        return 1;
    } else if (cp < 0x800) {
        out[0] = @intCast(0xC0 | (cp >> 6));
        out[1] = @intCast(0x80 | (cp & 0x3F));
        return 2;
    } else if (cp < 0x10000) {
        out[0] = @intCast(0xE0 | (cp >> 12));
        out[1] = @intCast(0x80 | ((cp >> 6) & 0x3F));
        out[2] = @intCast(0x80 | (cp & 0x3F));
        return 3;
    } else {
        out[0] = @intCast(0xF0 | (cp >> 18));
        out[1] = @intCast(0x80 | ((cp >> 12) & 0x3F));
        out[2] = @intCast(0x80 | ((cp >> 6) & 0x3F));
        out[3] = @intCast(0x80 | (cp & 0x3F));
        return 4;
    }
}

test "entities: decodeAt resolves the corpus forms" {
    try std.testing.expectEqualStrings("\u{A0} & © Æ Ď", decodeAll("&nbsp; &amp; &copy; &AElig; &Dcaron;"));
    try std.testing.expectEqualStrings("# Ӓ Ϡ �", decodeAll("&#35; &#1234; &#992; &#0;"));
    try std.testing.expectEqualStrings("\" ആ ಫ", decodeAll("&#X22; &#XD06; &#xcab;"));
    // Nonentities stay literal.
    try std.testing.expectEqualStrings("&nbsp &x; &#; &#x;", decodeAll("&nbsp &x; &#; &#x;"));
    try std.testing.expectEqualStrings("&#87654321;", decodeAll("&#87654321;"));
    try std.testing.expectEqualStrings("&#abcdef0;", decodeAll("&#abcdef0;"));
    try std.testing.expectEqualStrings("&copy", decodeAll("&copy"));
    try std.testing.expectEqualStrings("&MadeUpEntity;", decodeAll("&MadeUpEntity;"));
    // Structural characters stay literal (&#42; is not a delimiter).
    try std.testing.expectEqualStrings("*foo*", decodeAll("&#42;foo&#42;"));
    try std.testing.expectEqualStrings("foo\n\nbar", decodeAll("foo&#10;&#10;bar"));
    try std.testing.expectEqualStrings("\tfoo", decodeAll("&#9;foo"));
}

test "entities: decodeAt edge cases" {
    // A prefix of a real name is not an entity.
    try std.testing.expectEqualStrings("&noti;", decodeAll("&noti;"));
    // Entity names are exact (case-sensitive): mixed case is not a reference.
    try std.testing.expectEqualStrings("&NotEQual;", decodeAll("&NotEQual;"));
    try std.testing.expectEqualStrings("©", decodeAll("&copy;"));
    // Two-codepoint entity.
    try std.testing.expectEqualStrings("≧̸", decodeAll("&ngE;"));
    // & at the very end.
    try std.testing.expectEqualStrings("a &", decodeAll("a &"));
}

var decode_scratch: [256]u8 = undefined;
fn decodeAll(src: []const u8) []const u8 {
    var n: usize = 0;
    var i: usize = 0;
    while (i < src.len) {
        if (src[i] == '&') {
            if (decodeAt(src, i)) |dec| {
                @memcpy(decode_scratch[n .. n + dec.len], dec.bytes[0..dec.len]);
                n += dec.len;
                i = dec.next;
                continue;
            }
        }
        decode_scratch[n] = src[i];
        n += 1;
        i += 1;
    }
    return decode_scratch[0..n];
}
